package com.iingstd.photoprint;
import android.app.*;import android.os.*;import android.widget.*;import android.graphics.Color;import java.net.*;import java.io.*;
public class MainActivity extends Activity {
 android.net.nsd.NsdManager nsd; android.net.nsd.NsdManager.DiscoveryListener listener;
 boolean resolving;
 EditText printUri; TextView printStatus; Spinner paper,quality,color,type; EditText copies;
 @Override protected void onActivityResult(int request,int result,android.content.Intent data){super.onActivityResult(request,result,data);if(request!=42||result!=RESULT_OK||data==null||data.getData()==null)return;android.net.Uri file=data.getData();String mime=getContentResolver().getType(file);if(!"application/pdf".equals(mime)&&!"image/jpeg".equals(mime)){printStatus.setText("Format belum didukung");return;}String address=printUri.getText().toString().trim();String[] media={"iso_a4_210x297mm","custom_f4_210x330mm","na_legal_8.5x14in","na_index-4x6_4x6in"};String selected=media[paper.getSelectedItemPosition()];int qual=new int[]{0,3,4,5}[quality.getSelectedItemPosition()];String col=new String[]{"","color","monochrome"}[color.getSelectedItemPosition()];String typ=new String[]{"","stationery","photographic-glossy","photographic-matte"}[type.getSelectedItemPosition()];int count;try{count=Integer.parseInt(copies.getText().toString());if(count<1||count>99)throw new Exception();}catch(Exception e){printStatus.setText("Jumlah salinan harus 1–99");return;}new AlertDialog.Builder(this).setView(preview(file,mime)).setTitle("Preview sebelum cetak").setMessage("Ukuran: "+paper.getSelectedItem()+"\\nFormat: "+mime).setNegativeButton("Batal",null).setPositiveButton("Cetak",(dialog,which)->{printStatus.setText("Mengirim...");new Thread(()->{String msg;try(InputStream in=getContentResolver().openInputStream(file)){if(in==null)throw new IOException("File tidak dapat dibuka");msg=Ipp.print(address,mime,in,selected,qual,col,typ,count);}catch(Exception e){msg="Gagal: "+e.getMessage();}String finalMsg=msg;runOnUiThread(()->printStatus.setText(finalMsg));}).start();}).show();}

 android.view.View preview(android.net.Uri file,String mime){
 LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.setPadding(16,8,16,8);
 ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);layout.addView(image,new LinearLayout.LayoutParams(-1,(int)(300*getResources().getDisplayMetrics().density)));
 TextView info=new TextView(this);layout.addView(info);info.setText("Memuat preview...");
 new Thread(()->{android.graphics.Bitmap bitmap=null;String message;
 try{if("application/pdf".equals(mime)){try(android.os.ParcelFileDescriptor fd=getContentResolver().openFileDescriptor(file,"r");android.graphics.pdf.PdfRenderer renderer=new android.graphics.pdf.PdfRenderer(fd)){int pages=renderer.getPageCount();try(android.graphics.pdf.PdfRenderer.Page page=renderer.openPage(0)){float scale=Math.min(1000f/page.getWidth(),1000f/page.getHeight());bitmap=android.graphics.Bitmap.createBitmap(Math.max(1,(int)(page.getWidth()*scale)),Math.max(1,(int)(page.getHeight()*scale)),android.graphics.Bitmap.Config.ARGB_8888);bitmap.eraseColor(android.graphics.Color.WHITE);page.render(bitmap,null,null,android.graphics.pdf.PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);}message="Preview halaman 1 dari "+pages+"; semua halaman dikirim.";}}
 else if(android.os.Build.VERSION.SDK_INT>=28){bitmap=android.graphics.ImageDecoder.decodeBitmap(android.graphics.ImageDecoder.createSource(getContentResolver(),file),(decoder,header,source)->{int w=header.getSize().getWidth(),h=header.getSize().getHeight();float scale=Math.min(1f,1000f/Math.max(w,h));decoder.setTargetSize(Math.max(1,(int)(w*scale)),Math.max(1,(int)(h*scale)));});message="Preview foto; posisi cetak ditentukan printer.";}else{message="Preview JPEG memerlukan Android 9 atau lebih baru.";}}
 catch(Exception e){message="Preview gagal: "+e.getMessage();}
 android.graphics.Bitmap b=bitmap;String msg=message;runOnUiThread(()->{if(b!=null)image.setImageBitmap(b);info.setText(msg);});}).start();return layout;
 }
 void discover(EditText uri, TextView status){
 if(listener!=null)return;
 nsd=(android.net.nsd.NsdManager)getSystemService(NSD_SERVICE);
 listener=new android.net.nsd.NsdManager.DiscoveryListener(){
 public void onDiscoveryStarted(String t){runOnUiThread(()->status.setText("Mencari printer IPP..."));}
 public void onDiscoveryStopped(String t){}
 public void onStartDiscoveryFailed(String t,int e){runOnUiThread(()->{listener=null;status.setText("Pencarian gagal: "+e);});}
 public void onStopDiscoveryFailed(String t,int e){}
 public void onServiceLost(android.net.nsd.NsdServiceInfo s){}
 public void onServiceFound(android.net.nsd.NsdServiceInfo s){runOnUiThread(()->{if(resolving||listener==null)return;resolving=true;nsd.resolveService(s,new android.net.nsd.NsdManager.ResolveListener(){
 public void onResolveFailed(android.net.nsd.NsdServiceInfo i,int e){runOnUiThread(()->{resolving=false;status.setText("Resolusi printer gagal: "+e);});}
 public void onServiceResolved(android.net.nsd.NsdServiceInfo i){runOnUiThread(()->{resolving=false;if(listener==null||i.getHost()==null)return;try{byte[] rp=i.getAttributes().get("rp");String path=rp==null?"ipp/print":new String(rp,java.nio.charset.StandardCharsets.UTF_8);if(!path.startsWith("/"))path="/"+path;String address=new URI("ipp",null,i.getHost().getHostAddress(),i.getPort(),path,null,null).toString();uri.setText(address);status.setText("Ditemukan: "+i.getServiceName()+" — tekan Uji koneksi");stopDiscovery();}catch(Exception e){status.setText(e.toString());}});}
 });});}
 };
 try{nsd.discoverServices("_ipp._tcp.",android.net.nsd.NsdManager.PROTOCOL_DNS_SD,listener);new Handler(Looper.getMainLooper()).postDelayed(()->{if(listener!=null){stopDiscovery();status.setText("Pencarian selesai. Masukkan IP manual jika belum ditemukan.");}},15000);}catch(Exception e){listener=null;status.setText(e.toString());}
 }
 void stopDiscovery(){if(listener!=null){try{nsd.stopServiceDiscovery(listener);}catch(Exception ignored){}listener=null;}}
 @Override protected void onDestroy(){stopDiscovery();super.onDestroy();}

 Spinner option(LinearLayout l,String label,String[] values){TextView t=new TextView(this);t.setText(label);l.addView(t);Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,values));l.addView(s);return s;}
 public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(32,64,32,32);ScrollView scroll=new ScrollView(this);scroll.addView(l);setContentView(scroll); TextView title=new TextView(this);title.setText("IING STD Photo Print");title.setTextSize(26);title.setTextColor(0xff007f80);l.addView(title); EditText uri=new EditText(this);uri.setHint("ipp://192.168.1.100:631/ipp/print");uri.setText(getPreferences(0).getString("uri",""));l.addView(uri);Button probe=new Button(this);probe.setText("Uji koneksi printer IPP");l.addView(probe);TextView status=new TextView(this);l.addView(status);printUri=uri;printStatus=status;paper=new Spinner(this);paper.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"A4","F4 210 x 330 mm","Legal","4R"}));l.addView(paper);quality=option(l,"Kualitas",new String[]{"Default printer","Draft","Normal","High"});color=option(l,"Warna",new String[]{"Default printer","Berwarna","Hitam putih"});type=option(l,"Jenis kertas",new String[]{"Default printer","Plain paper","Glossy","Matte"});copies=new EditText(this);copies.setInputType(2);copies.setHint("Jumlah salinan");copies.setText("1");l.addView(copies);Button print=new Button(this);print.setText("Pilih PDF / JPEG untuk cetak");l.addView(print);print.setOnClickListener(v->{android.content.Intent i=new android.content.Intent(android.content.Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.putExtra(android.content.Intent.EXTRA_MIME_TYPES,new String[]{"application/pdf","image/jpeg"});i.addCategory(android.content.Intent.CATEGORY_OPENABLE);startActivityForResult(i,42);});Button scan=new Button(this);scan.setText("Cari printer Wi-Fi");l.addView(scan);scan.setOnClickListener(v->discover(uri,status));probe.setOnClickListener(v->{String s=uri.getText().toString().trim();getPreferences(0).edit().putString("uri",s).apply();status.setText("Memeriksa printer...");probe.setEnabled(false);new Thread(()->{String result;try{result=Ipp.probe(s);}catch(Exception e){result="Gagal: "+e.getMessage();}String r=result;runOnUiThread(()->{status.setText(r);probe.setEnabled(true);});}).start();}); }
}
